let CUR_ENV=null,CUR_HUMANP=0,CUR_STONEP=0;

/* ---------- 乱数と補助 ---------- */
function hashStr(s){let h=1779033703^s.length;for(let i=0;i<s.length;i++){h=Math.imul(h^s.charCodeAt(i),3432918353);h=h<<13|h>>>19}h=Math.imul(h^h>>>16,2246822507);h=Math.imul(h^h>>>13,3266489909);return ((h^h>>>16)>>>0)||1}
function mkRng(seed){let a=seed>>>0;return function(){a=(a+0x6D2B79F5)|0;let t=Math.imul(a^a>>>15,1|a);t=(t+Math.imul(t^t>>>7,61|t))^t;return((t^t>>>14)>>>0)/4294967296}}
function pick(R,a){return a[Math.floor(R()*a.length)]}
function rg(R,a,b){return a+(b-a)*R()}
function clamp(x,a,b){return Math.max(a,Math.min(b,x))}
function wpick(R,items,wf){let tot=0;const ws=items.map(i=>{const w=wf(i);tot+=w;return w});let x=R()*tot;for(let i=0;i<items.length;i++){x-=ws[i];if(x<=0)return items[i]}return items[items.length-1]}
function fmt(y){
  if(y>=1e8){let s=(y/1e8).toFixed(2).replace(/0+$/,'').replace(/\.$/,'');return s+'億年'}
  if(y>=1e4)return Math.round(y/1e4).toLocaleString('ja-JP')+'万年';
  return Math.max(1,Math.round(y)).toLocaleString('ja-JP')+'年';
}

/* ---------- 生物のゲノム(パーツ構成) ---------- */
function mkPal(R,hue){
  const h=((hue==null?Math.floor(R()*360):hue)%360+360)%360;
  return {hue:h,a:`hsl(${h},55%,58%)`,b:`hsl(${(h+18)%360},50%,36%)`,c:`hsl(${(h+170)%360},72%,66%)`,k:'#15152b',w:'#f4f4ff'};
}
const NOHUMAN={head:'human',body:'suit',legs:'trousers',arms:'sleeve'};
const NOSTONE={head:'pebble',body:'boulder',legs:'stonelegs'};
function randPart(R,cat){
  const b=CUR_ENV&&TYPE_BIAS[CUR_ENV];
  if(b&&b[cat]&&R()<.7)return pick(R,b[cat]);
  const ks=Object.keys(PARTS[cat]).filter(k=>(NOHUMAN[cat]!==k&&NOSTONE[cat]!==k)||R()<.15);
  return pick(R,ks);
}
function stoneGenome(R){
  const sh=Math.floor(R()*40)+15;
  return {kind:'form',head:'pebble',body:'boulder',legs:'stonelegs',arms:pick(R,['claw','pincer']),tail:null,wings:null,noEyes:true,
    pal:{hue:sh,a:'#a39787',b:'#6e655c',c:'#d9c9a3',k:'#15152b',w:'#f4f4ff'}};
}
function humanGenome(R){
  const skin=pick(R,['#f2c9a5','#e0a97d','#c68a5d','#8d5a3a','#5e3b26']);
  const hair=pick(R,['#2a1c14','#4a3226','#b5733a','#d8c27a','#9a9aa8']);
  const h=Math.floor(R()*360);
  return {kind:'form',head:'human',body:'suit',legs:'trousers',arms:'sleeve',tail:null,wings:null,noEyes:false,
    pal:{hue:h,a:skin,b:`hsl(${h},45%,45%)`,c:hair,k:'#15152b',w:'#f4f4ff'}};
}
function newGenome(R,stage,pal){
  pal=pal||mkPal(R);
  if(stage===0)return {kind:'micro',pal};
  if(stage===1)return {kind:'form',pal,body:(CUR_ENV&&TYPE_BIAS[CUR_ENV]&&R()<.7)?pick(R,TYPE_BIAS[CUR_ENV].body):pick(R,['blob','segment','crystal','trunk','octo','wisp','shell']),head:null,legs:null,arms:null,tail:null,wings:null,noEyes:true};
  const g={kind:'form',pal,head:randPart(R,'head'),body:randPart(R,'body'),legs:null,arms:null,tail:null,wings:null,noEyes:R()<.15};
  if(stage===2&&R()<.08)g.body=null;
  g.legs=R()<.6?randPart(R,'legs'):null;
  g.arms=R()<(stage>=3?.7:.35)?randPart(R,'arms'):null;
  g.tail=R()<.4?randPart(R,'tail'):null;
  g.wings=R()<.22?randPart(R,'wings'):null;
  return g;
}
function mutate(R,g,n){
  const h=JSON.parse(JSON.stringify(g));const keys=['head','body','legs','arms','tail','wings'];
  for(let i=0;i<n;i++){
    const k=pick(R,keys);
    if(k==='head')h.head=randPart(R,'head');
    else if(k==='body')h.body=R()<.06?null:randPart(R,'body');
    else h[k]=R()<.45?null:randPart(R,k==='tail'?'tail':k);
  }
  if(R()<.2)h.noEyes=!h.noEyes;
  h.pal=mkPal(R,h.pal.hue+Math.floor(rg(R,-30,30)));
  if(!h.head&&!h.body)h.body=randPart(R,'body');
  return h;
}
function evolveTo(R,g,stage,n,heavy){
  let h;
  if(stage===0)h=newGenome(R,0,mkPal(R,g.pal.hue+Math.floor(rg(R,-30,30))));
  else if(g.kind==='micro'||stage===1)h=newGenome(R,stage,mkPal(R,g.pal.hue+Math.floor(rg(R,-25,25))));
  else if(!g.head&&!g.body)h=newGenome(R,stage,mkPal(R,g.pal.hue));
  else if(stage===2&&!g.head)h=newGenome(R,2,mkPal(R,g.pal.hue));
  else h=mutate(R,g,n+(heavy?2:0));
  if(stage>=4){h.head=h.head||randPart(R,'head');h.body=h.body||'humanoid';h.arms=h.arms||randPart(R,'arms');h.noEyes=false;if(CUR_HUMANP&&R()<CUR_HUMANP)h=humanGenome(R);else if(CUR_STONEP&&R()<CUR_STONEP)h=stoneGenome(R);}
  return h;
}
function hybrid(R,a,b){
  const h=JSON.parse(JSON.stringify(a));
  ['head','body','legs','arms','tail','wings'].forEach(k=>{if(R()<.5)h[k]=b[k];});
  if(!h.head&&!h.body)h.body='humanoid';
  h.kind='form';h.noEyes=false;h.pal=mkPal(R,(a.pal.hue+b.pal.hue)/2+180*(R()<.3));
  return h;
}
function speciesName(R,g,stage){
  if(g.kind==='micro')return pick(R,['熱水','塩湖','氷下','硫黄','光合成','深海','地殻','岩石内','雲中'])+pick(R,['菌','藻','微生物']);
  if(!g.head)return `${PARTS.body[g.body].b}の群体`;
  if(g.head==='human'&&(g.body==='suit'||g.body==='humanoid'))return '人類';
  if(g.body==='boulder'&&(g.head==='pebble'||g.noEyes))return stage>=4?'石の生物':'岩殻の生き物';
  const H=PARTS.head[g.head].jp;
  let nm;
  if(!g.body)nm=`${H}頭の浮遊体`;
  else if(g.body==='humanoid'||g.body==='suit')nm=`${H}人`;
  else nm=`${H}頭の${PARTS.body[g.body].b}生物`;
  if(g.noEyes&&stage>=2)nm='盲目の'+nm;
  else if(stage>=2&&stage<4&&R()<.3)nm=pick(R,['発光','大型','夜行性','硬殻','群生','毒を持つ'])+nm;
  return nm;
}

/* ---------- 描画: 32x32 のグリッドに合成して縁取りを付ける ---------- */
function composeGrid(g){
  const W=32,grid=new Array(W*W).fill(null),pal=g.pal;
  const put=(spr,x0,y0,mir,noEye)=>{
    spr.forEach((row,yy)=>{for(let xx=0;xx<row.length;xx++){
      let ch=row[mir?row.length-1-xx:xx];if(ch==='.')continue;
      if(noEye&&(ch==='k'||ch==='w'))ch='a';
      const x=x0+xx,y=y0+yy;if(x<0||y<0||x>=W||y>=W)continue;
      grid[y*W+x]=pal[ch]||pal.a;
    }});
  };
  if(g.kind==='micro'){
    const cells=[[16,16,4],[10,13,3],[22,19,3],[14,23,2],[20,10,2],[8,21,2],[24,12,2]];
    cells.forEach(([cx,cy,r],i)=>{for(let y=-r;y<=r;y++)for(let x=-r;x<=r;x++){
      if(x*x+y*y<=r*r+1){const px=cx+x,py=cy+y;grid[py*W+px]=(x*x+y*y<=1&&r>2)?pal.c:(i%2?pal.b:pal.a)}}});
  }else{
    const hd=!!g.head,bl=!!g.body,P=PARTS;
    const yH=bl?7:11,yB=hd?14:11;
    const yA=bl?yB+2:yH+2,yL=bl?yB+10:yH+8,yT=bl?yB+5:yH+3,yW=bl?yB-5:yH-3;
    if(g.wings){put(P.wings[g.wings].s,4,yW,false);put(P.wings[g.wings].s,22,yW,true);}
    if(g.tail)put(P.tail[g.tail].s,4,yT,false);
    if(g.legs)put(P.legs[g.legs].s,11,yL,false);
    if(bl)put(P.body[g.body].s,11,yB,false);
    if(g.arms){put(P.arms[g.arms].s,7,yA,false);put(P.arms[g.arms].s,21,yA,true);}
    if(hd)put(P.head[g.head].s,11,yH,false,g.noEyes);
  }
  const out=grid.slice();
  for(let y=0;y<W;y++)for(let x=0;x<W;x++){
    if(grid[y*W+x])continue;
    if((x>0&&grid[y*W+x-1])||(x<W-1&&grid[y*W+x+1])||(y>0&&grid[(y-1)*W+x])||(y<W-1&&grid[(y+1)*W+x]))out[y*W+x]=pal.k;
  }
  return out;
}
function drawGenome(cv,g){
  const W=32,ctx=cv.getContext('2d');cv.width=W;cv.height=W;ctx.clearRect(0,0,W,W);
  const grid=composeGrid(g);
  for(let y=0;y<W;y++)for(let x=0;x<W;x++){const c=grid[y*W+x];if(c){ctx.fillStyle=c;ctx.fillRect(x,y,1,1)}}
}
