function specFor(R,T){
  const S=SPECS[T.id],r=rg(R,S.r[0],S.r[1]),g=rg(R,S.g[0],S.g[1]),tp=Math.round(rg(R,S.temp[0],S.temp[1]));
  const moons=T.id==='moon'?0:(T.id==='gas'?4+Math.floor(R()*20):Math.floor(R()*4));
  let day=Math.round(rg(R,10,50))+'時間',year=Math.round(rg(R,120,900))+'日';
  if(T.id==='tidal')day='公転周期と同じ(自転しない)';
  if(T.id==='rogue')year='公転しない';
  if(T.id==='bhplanet')year=Math.round(rg(R,6,40))+'時間';
  if(T.id==='binary')year=Math.round(rg(R,300,900))+'日';
  return {radius:`地球の${r.toFixed(1)}倍`,gravity:`${g.toFixed(1)}G`,day,year,temp:`${tp}℃`,atm:pick(R,S.atm),moons:T.id==='moon'?'母惑星の衛星':(moons+'個'),extra:pick(R,S.ex),desc:S.d};
}

