const ENDING_FATE_SURVIVE=.4;

function newPlanet(R,id,sysIdx,starName,tStar){
  const ty=wpick(R,TYPES,t=>t.w);
  return {id,name:null,sys:sysIdx,star:starName,type:ty,tForm:tStar+rg(R,0,1.2e8),
    spec:null,slow:0,m:{},events:[],lineage:[],outcome:null,civ:null,civStart:null,trait:null,sense:null,finalG:null,species:null,variant:0,tLife:null,seeded:false};
}
function initSpec(R,p){p.spec=specFor(R,p.type);if(p.type.id==='bhplanet'){p.slow=Math.round(rg(R,3,9));p.spec.extra=`時間の流れが遅く、この星の1時間は外の宇宙の約${p.slow}年にあたる`}
}
function simulate(seed,variants,mods){
  variants=variants||{};
  const R=mkRng(hashStr(seed)),gal={cosmic:null,seed,name:mkName(R)+'銀河',planets:[],systems:[],contacts:[],variants};
  const nSys=2+Math.floor(R()*2),used=new Set();let pid=0;
  for(let s=0;s<nSys;s++){
    const star=mkName(R)+'星系',tStar=rg(R,7.6e9,1.04e10),n=(s===0?2:1)+Math.floor(R()*2);
    const so={name:star,planets:[]};gal.systems.push(so);
    for(let k=0;k<n&&gal.planets.length<6;k++){
      const p=newPlanet(R,pid++,s,star,tStar);
      let nm=mkName(R);while(used.has(nm))nm=mkName(R);used.add(nm);p.name=nm;
      gal.planets.push(p);so.planets.push(p.id);
    }
  }
  gal.planets.forEach(p=>{initSpec(mkRng(hashStr(seed+'#spec'+p.id)),p);});
  gal.mods=mods||[];gal.mods.forEach(x=>{const p=gal.planets[x.p];if(p)p.m[x.k]=true});
  gal.planets.forEach(p=>{
    p.variant=variants[p.id]||0;
    simPlanet(mkRng(hashStr(seed+'#'+p.id+'v'+p.variant)),p);
  });
  const Rg=mkRng(hashStr(seed+'#contacts'+JSON.stringify(variants)));
  panspermia(Rg,gal);
  resolveContacts(Rg,gal);
  cosmicEvent(Rg,gal);
  CUR_ENV=null;CUR_HUMANP=0;CUR_STONEP=0;
  gal.planets.forEach(finalize);
  const civs=gal.planets.filter(p=>p.civStart);
  gal.tObs=civs.length?Math.max.apply(null,civs.map(p=>p.civStart))+rg(Rg,3e4,4e5):1.39e10;
  externalEvent(mkRng(hashStr(seed+'#ext'+JSON.stringify(variants))),gal);
  if(gal.ext)gal.planets.forEach(finalize);
  wonders(mkRng(hashStr(seed+'#won'+JSON.stringify(variants))),gal);
  gal.planets.forEach(p=>{p.obs=observe(p,gal.tObs)});
  return gal;
}

function simPlanet(R,p){
  const T=p.type;CUR_ENV=T.id;CUR_HUMANP=HUMANP[T.id]||.03;CUR_STONEP=STONEP[T.id]||.02;
  const SL=p.slow?1.5:1,M=p.m||{};let dfl=false,imp=false;
  const ev=(t,kind,title,text,major,g)=>{p.events.push({t,kind,title,text,major:!!major,g:g||null,planet:p.id})};
  ev(p.tForm,'birth',p.name+'の誕生',`${p.star}の周囲で、${T.jp}として形づくられた。`,true);
  if(R()<.6)ev(p.tForm+rg(R,3e8,7e8),'disaster','原始の天体衝突','形成直後の惑星に小天体が次々と降り注ぎ、表面が溶けては固まった。',false);
  if(M.water)ev(p.tForm+rg(R,2e8,6e8),'evolve','彗星が水を運ぶ','氷を多く含む彗星の群れが軌道を変えて降り注ぎ、乾いた星に大量の水がもたらされた。',true);
  const hab=M.water?Math.min(.97,T.hab+.3):T.hab,lifeP=(M.seed?Math.max(.95,hab*LIFEK[RARE]):hab*LIFEK[RARE])*rg(R,.8,1.2),tLife=p.tForm+rg(R,4e8,1.3e9);
  if(R()>lifeP||tLife>T_END){
    const tb=Math.min(T_END,p.tForm+rg(R,1e9,3e9));
    ev(tb,'end','生命は現れなかった',T.barren,true);
    p.outcome={kind:'barren',title:'生命は生まれなかった',text:T.barren};return;
  }
  p.tLife=tLife;
  let t=tLife,stage=0,g=newGenome(R,0),cat=0;
  const addLin=(tt,gg,st)=>{const nm=speciesName(R,gg,st);p.lineage.push({stage:st,name:nm,g:gg,t:tt,fate:null});return nm};
  const lastLin=()=>p.lineage[p.lineage.length-1];
  let sp=addLin(t,g,0);
  ev(t,'life','最初の生命',`${T.medium}で${sp}が誕生した。生命の歴史がここから始まる。`+(p.slow?`(この星では時間がゆっくり流れ、外の宇宙の${p.slow}年が1時間に押し込まれている)`:''),true,g);
  if(M.seed){ev(Math.max(p.tForm+1e8,tLife-3e6),'life','生命の種を乗せた隕石','別の星から飛んできた岩に、乾燥と放射線に耐える微生物が閉じ込められていた。落下の熱を生き延びた種が、水のある場所に根づいた。',true);p.seeded=true}
  let flavorUsed={};
  while(true){
    const d=rg(R,STG[stage].dur[0],STG[stage].dur[1])*SL;
    let tn=t+d;
    if(tn>T_END){
      ev(T_END,'end','観測の終わり',`観測が終わる時点で${sp}が暮らしている。知性を持つ種はまだ現れていない。`,true);
      p.outcome={kind:'evolving',title:'進化の途上',text:`観測が終わる時点で${sp}が暮らしているが、知性を持つ種はまだ現れていない。続きは誰にも分からない。`};
      return;
    }
    /* 進化の小さなできごと */
    if(FLAVOR[stage]&&R()<.8){
      const f=pick(R,FLAVOR[stage]);
      if(!flavorUsed[f]){flavorUsed[f]=1;ev(t+d*rg(R,.3,.8),'evolve',['微生物の時代','群体の時代','生態系の拡大','感覚の発達'][stage],f,false);}
    }
    let impNow=false;
    if(cat<3&&((M.impact&&!imp&&stage>=1&&(impNow=imp=true))||R()<((M.moon&&stage>=2)?.2:.42))){
      const c=impNow?CATS[0]:pick(R,CATS),tc=t+d*rg(R,.2,.9);cat++;
      const sev=impNow?(R()<.2?'sterile':'mass'):wpick(R,['set','mass','sterile'],s=>c.w[s]);
      if(M.deflect&&!dfl&&!impNow){dfl=true;ev(tc,'disaster','小惑星の衝突を回避',`${c.jp}につながるはずだった天体の軌道が早い段階で変わり、${sp}の世界は大きな被害を免れた。`,true);continue}
      if(sev==='sterile'){
        ev(tc,'disaster',c.jp,`${c.t}地表の生命はほぼ全滅した。`,true);
        lastLin().fate=`${c.jp}で絶滅`;
        if(R()<.3&&tc+8e8<T_END){
          t=tc+rg(R,3e8,9e8);stage=0;g=newGenome(R,0);sp=addLin(t,g,0);
          ev(t,'life','二度目の生命',`地下に残った化学の種から、${sp}が再び現れた。`,true,g);continue;
        }
        ev(tc+1e6,'end','生命は途絶えた',`${c.jp}で生態系が崩壊し、再び命が芽吹くことはなかった。`,true);
        p.outcome={kind:'extinct',title:'生命は途絶えた',text:`${c.jp}で生態系が崩壊し、再び命が芽吹くことはなかった。`};return;
      }
      if(sev==='mass'){
        lastLin().fate=`${c.jp}で絶滅`;
        stage=Math.max(0,stage-1);g=evolveTo(R,g,stage,3,true);t=tc+rg(R,2e7,2e8);
        sp=addLin(t,g,stage);
        ev(tc,'disaster',c.jp,`${c.t}多くの種が絶え、生き残りの中から${sp}が台頭した。`,true,g);continue;
      }
      /* setback */
      lastLin().fate='環境の激変に適応して分岐';
      g=mutate(R,g.kind==='micro'?newGenome(R,1):g,2);
      if(stage===0)g=newGenome(R,0,mkPal(R,g.pal.hue));
      sp=addLin(tc,g,stage);
      ev(tc,'disaster',c.jp,`${c.t}生き延びた系統が、${sp}として適応し直した。`,true,g);
      tn=tn+d*rg(R,.3,.8);
      if(tn>T_END){tn=T_END-1;}
    }
    if(stage===3&&STALLP[RARE]&&R()<STALLP[RARE]*(M.moon?.35:1)){
      ev(T_END,'end','観測の終わり',`観測が終わる時点で${sp}が暮らしている。生態系の頂点には立ったが、知性にまでは進まなかった。`,true);
      p.outcome={kind:'evolving',title:'進化の途上',text:`${sp}は生態系の頂点に立ったが、知性にまでは進まなかった。続きは誰にも分からない。`};return;
    }
    if(stage===3&&R()<.1)ev(tn-d*.15,'evolve','黒い石板','真っ黒な石板が平原に現れた。触れた群れは道具の使い方を急速に学び、知性への道を一気に駆け上がった。',true);
    stage++;
    lastLin().fate='進化し、次の系統へ';
    t=tn;g=evolveTo(R,g,stage,2);sp=addLin(t,g,stage);
    if(stage<4){
      const tx=[null,`細胞が集まって${sp}が現れた。`,`体が大きくなり、${sp}が${T.medium}の周辺に広がった。`,`感覚器と神経を発達させた${sp}が、生態系の上位に立った。`][stage];
      ev(t,'evolve',STAGE_TITLE[stage],tx,true,g);
    }else break;
  }
  /* 知性の誕生 */
  const trait=pick(R,TRAITS);p.trait=trait;p.sense=pick(R,SENSES);p.civStart=t;
  p.civ={start:t,spaceStart:null,end:T_END,alive:true,stage:0};
  ev(t,'mind','知性の誕生',`${sp}が道具と言語を持った。主な感覚は${p.sense}で、気質は${trait.jp}。火を使い、小さな群れで暮らし始める。`,true,g);
  let tc=t,done=false;
  for(let i=0;i<CIV.length;i++){
    if(i>=1)ev(tc,'civ',CIV[i].name,CIV[i].t(sp)+`(カルダシェフ尺度 ${CIV[i].k})`,i>=4);
    if(M.res&&i===2)ev(tc+1,'civ','資源小惑星の捕獲','金属を豊富に含む小惑星が地球近傍の軌道に引き込まれ、資源の奪い合いが和らいだ。',false);
    if(i===4)p.civ.spaceStart=tc;
    p.civ.stage=i;
    const d=rg(R,CIV[i].dur[0],CIV[i].dur[1])*SL,tn=tc+d;
    if(tn>T_END){
      ev(T_END,'end','観測の終わり',`観測が終わる時点でも${sp}の文明は続いている。`,true);
      p.outcome={kind:'thriving',title:`${CIV[i].name}の途上`,text:`観測が終わる時点でも${sp}の文明は続いている。現在は「${CIV[i].name}」(カルダシェフ尺度 ${CIV[i].k})にあたる。`};
      return;
    }
    if(R()<CIV[i].risk*trait.risk*(M.res?.65:1)){
      const tcol=tc+d*rg(R,.2,.95);
      const cause=wpick(R,CAUSES.filter(c=>c.st.includes(i)),c=>(c.w&&c.w[trait.id])||1);
      p.civ.end=tcol;p.civ.alive=false;p.civ.cause=cause.jp;
      ev(tcol,'end',cause.jp+'による崩壊',cause.t(sp),true);
      if(R()<ENDING_FATE_SURVIVE){
        p.outcome={kind:'ruins',title:'文明は崩壊し、種だけが残った',text:`${cause.t(sp)}生き延びた${sp}は原始的な暮らしに戻り、いまも細々と続いている。`};
      }else{
        lastLin().fate='絶滅';
        p.outcome={kind:'extinct',title:`${sp}は滅んだ`,text:`${cause.t(sp)}${sp}は絶え、廃墟だけが残った。`};
        if(R()<.2){
          const g2=evolveTo(R,newGenome(R,1),3,3),ts=tcol+rg(R,5e4,5e5),s2=addLin(ts,g2,3);
          ev(ts,'evolve','次の支配者の芽',`${sp}の廃墟のそばで、${s2}が道具を使い始めた。廃墟を見上げる彼らが次の文明を築くかもしれない。`,true,g2);
          p.outcome={kind:'ruins',title:`${sp}の後に${s2}が育つ`,text:`${cause.t(sp)}${sp}は絶えたが、廃墟のそばで${s2}が知性の芽を見せ始めている。`};
        }
      }
      return;
    }
    tc=tn;
  }
  const a=wpick(R,ASC,x=>(x.w&&x.w[trait.id])||1);
  p.civ.ascended=a.jp;
  ev(tc,'end',a.jp,a.t(sp),true);
  p.outcome={kind:'ascended',title:a.jp,text:a.t(sp)};
}

/* 同じ星系で先に生命が生まれた星から、種が届くことがある */
function panspermia(R,gal){
  gal.systems.forEach(so=>{
    const ps=so.planets.map(i=>gal.planets[i]).filter(p=>p.tLife).sort((a,b)=>a.tLife-b.tLife);
    if(ps.length<2||R()>.3)return;
    const a=ps[0],b=ps[1],t=b.tLife+1e7;
    b.seeded=true;
    a.events.push({t:t,kind:'life',title:'生命の種が旅立つ',text:`衝突で飛び散った岩の欠片に微生物を乗せ、${b.name}へ届いた。`,major:true,g:null,planet:a.id});
    b.events.push({t:t,kind:'life',title:'パンスペルミア',text:`隣の${a.name}から飛来した岩に乗って、生命の種が届いた。`,major:true,g:null,planet:b.id});
  });
}

function trimTo(p,tEnd){p.events=p.events.filter(e=>e.kind!=='end'&&e.t<=tEnd+1)}
function endCiv(p,tEnd,title,text,outcome,fate){
  trimTo(p,tEnd);p.civ.end=tEnd;p.civ.alive=false;
  p.events.push({t:tEnd,kind:'end',title,text,major:true,g:null,planet:p.id});
  p.outcome=outcome;
  const l=p.lineage[p.lineage.length-1];if(l&&fate)l.fate=fate;
}
function reviveCiv(p){trimTo(p,p.civ.end);p.civ.end=T_END;p.civ.alive=true}

function resolveContacts(R,gal){
  const cs=gal.planets.filter(p=>p.civ),cand=[];
  for(let i=0;i<cs.length;i++)for(let j=i+1;j<cs.length;j++){
    const A=cs[i],B=cs[j],sa0=A.civ.spaceStart,sb0=B.civ.spaceStart;
    if(sa0==null&&sb0==null)continue;
    const asym=(sa0==null)!==(sb0==null);
    const s=asym?Math.max(sa0!=null?sa0:sb0,(sa0==null?A:B).civ.start):Math.max(sa0,sb0),e=Math.min(A.civ.end,B.civ.end),ov=e-s;
    if(ov<=0)continue;
    const same=A.sys===B.sys,prob=asym?(same?.6:.3):(same?.92:(ov>3e3?.75:.25));
    if(R()<prob)cand.push({A,B,t:s+Math.min(ov*.9,rg(R,50,1500)),same,asym});
  }
  cand.sort((x,y)=>x.t-y.t);
  cand.forEach(c=>{
    const A=c.A,B=c.B,t=c.t;
    if(!(A.civ.end>t)||!(B.civ.end>t))return;
    const sa=A.species=lastName(A),sb=B.species=lastName(B);
    const warN=(A.trait.id==='war'?1:0)+(B.trait.id==='war'?1:0)+(A.trait.id==='greedy'?.5:0)+(B.trait.id==='greedy'?.5:0);
    const peaceN=(A.trait.id==='peace'?1:0)+(B.trait.id==='peace'?1:0);
    const x=R(),wP=clamp(.2+.26*warN-.16*peaceN,.05,.75);
    let kind;
    if(c.asym)kind=wpick(R,['zoo','uplift','worship','infect','dark','war_one'],k=>({zoo:25,uplift:15,worship:15,infect:10,dark:10,war_one:10}[k]));
    else if(x<wP)kind=R()<.4?'war_mutual':(R()<.35?'dark':'war_one');
    else{
      const stoneIn=/石の生物/.test(sa+sb),gap=Math.abs(A.civ.stage-B.civ.stage);
      kind=wpick(R,['ally','merge','zoo','trade','silence','coop','uplift','worship','infect','gift'],k=>({ally:28+15*peaceN,merge:12,zoo:10,trade:10,silence:10,coop:14+(stoneIn?45:0)+8*peaceN,uplift:gap>=1?6:0,worship:gap>=1?5:0,infect:4,gift:6}[k]));
    }
    const rec={a:A.id,b:B.id,t,kind};gal.contacts.push(rec);
    const evC=(p,o,title,text)=>p.events.push({t,kind:'contact',title,text,major:true,g:null,planet:p.id,other:o.id});
    if(kind==='war_mutual'){
      const tA=Math.min(A.civ.end,t+rg(R,100,900)),tB=Math.min(B.civ.end,t+rg(R,100,900));
      evC(A,B,`${B.name}との接触`,`${sb}の文明と出会ったが、互いを理解できず戦争になった。`);
      evC(B,A,`${A.name}との接触`,`${sa}の文明と出会ったが、互いを理解できず戦争になった。`);
      [[A,tA,B,sa,sb],[B,tB,A,sb,sa]].forEach(([P,tt,O,sp,so])=>{
        const surv=R()<.3,tx=`${so}の文明との戦争が泥沼化し、${sp}の文明は共倒れで崩壊した。`;
        endCiv(P,tt,'異星戦争で共倒れ',tx,surv?{kind:'ruins',title:'異星戦争で崩壊、種は残る',text:tx+`生き延びた${sp}はいまも細々と続いている。`}:{kind:'extinct',title:`${sp}は滅んだ`,text:tx+`${sp}は絶えた。`},surv?null:'絶滅');
      });
    }else if(kind==='war_one'||kind==='dark'){
      const dark=kind==='dark';
      const sc=P=>R()+(P.trait.id==='war'?.25:0)+P.civ.stage*.08;
      let W=A,L=B;if(sc(B)>sc(A)){W=B;L=A}
      const sw=W===A?sa:sb,sl=L===A?sa:sb,tl=Math.min(L.civ.end,t+rg(R,100,600));
      if(dark){
        evC(W,L,`${L.name}を発見`,`${sl}の文明の信号を拾い、警告なしで先制攻撃を行った(暗黒森林)。`);
        evC(L,W,`${W.name}の奇襲`,`正体不明の攻撃を受け、反撃も交渉もできなかった。`);
      }else{
        evC(W,L,`${L.name}との戦争`,`${sl}の文明と衝突し、戦いに勝った。`);
        evC(L,W,`${W.name}との戦争`,`${sw}の文明と衝突し、敗れた。`);
      }
      const tx=dark?`${sw}の文明に先制攻撃を受け、${sl}の文明は何が起きたのかも分からないまま崩壊した。`:`${sw}の文明との戦争に敗れ、${sl}の文明は崩壊した。`;
      const surv=R()<.35;
      endCiv(L,tl,dark?'暗黒森林の一撃':'異星戦争に敗北',tx,surv?{kind:'ruins',title:'異星文明に敗れ、種は残る',text:tx+`生き延びた${sl}はいまも細々と続いている。`}:{kind:'extinct',title:`${sl}は滅んだ`,text:tx+`${sl}は絶えた。`},surv?null:'絶滅');
      if(['thriving','ascended','allied'].includes(W.outcome.kind))W.outcome.text+=dark?' その過程で、遠い星を一つ黙らせている。':' 異星文明との戦争にも勝利している。';
    }else if(kind==='ally'||kind==='trade'){
      evC(A,B,`${B.name}との同盟`,`${sb}の文明と出会い、${kind==='trade'?'交易と技術の交換を始めた':'共同で宇宙開発を進める同盟を結んだ'}。`);
      evC(B,A,`${A.name}との同盟`,`${sa}の文明と出会い、${kind==='trade'?'交易と技術の交換を始めた':'共同で宇宙開発を進める同盟を結んだ'}。`);
      [A,B].forEach(P=>{reviveCiv(P);const o=P===A?B:A,so=P===A?sb:sa;
        P.outcome={kind:'allied',title:kind==='trade'?'異星文明と交易を続ける':'異星文明と手を結んだ',text:`${P===A?sa:sb}は${o.name}の${so}と出会い、${kind==='trade'?'互いの産物と知識を交換し続けている':'同盟を結んで共に宇宙へ広がっている'}。`};
      });
    }else if(kind==='merge'){
      const hg=hybrid(R,A.lineage[A.lineage.length-1].g,B.lineage[B.lineage.length-1].g);
      const hn=speciesName(R,hg,4);
      [[A,B,sa,sb],[B,A,sb,sa]].forEach(([P,O,sp,so])=>{
        reviveCiv(P);
        evC(P,O,`${O.name}との融合`,`${so}の文明と出会い、長い交流の末に互いの遺伝子と文化が混ざり合った。`);
        const l=P.lineage[P.lineage.length-1];l.fate='異星種と融合し、新しい系統へ';
        P.lineage.push({stage:4,name:hn,g:hg,t:t+rg(R,1e3,5e3),fate:null});
        P.outcome={kind:'allied',title:'異星の種と融合した',text:`${sp}は${O.name}の${so}と融合し、どちらでもない新しい種「${hn}」として生き続けている。`};
        P.civ.mergedTo=hn;
      });
    }else if(kind==='coop'){
      const stone=/石の生物/.test(sa)?A:(/石の生物/.test(sb)?B:null);
      const crisis=['恒星が少しずつ暗くなり始めた危機','母星の寿命を延ばす計画','互いの星を襲う共通の災厄'][Math.floor(R()*3)];
      const mk=(P,O,sp,so)=>stone&&P!==stone?`${so}は石のような体と、音ではなく振動で話す生き物だった。長い手探りの通訳の末に友情が生まれ、${crisis}に二つの文明が力を合わせて立ち向かった。`:stone?`${so}と意思疎通に成功し、互いの知識を持ち寄って${crisis}を乗り越えた。`:`${so}の文明と信号の翻訳に成功し、${crisis}に力を合わせて立ち向かった。`;
      [[A,B,sa,sb],[B,A,sb,sa]].forEach(([P,O,sp,so])=>{reviveCiv(P);evC(P,O,`${O.name}との協力`,mk(P,O,sp,so));
        P.outcome={kind:'allied',title:'異星の友と危機を越えた',text:`${sp}は${O.name}の${so}と協力して宇宙の危機を乗り越え、いまも友として交信を続けている。`}});
    }else if(kind==='uplift'||kind==='worship'||kind==='gift'){
      const hi=A.civ.stage>=B.civ.stage?A:B,lo=hi===A?B:A,sh=hi===A?sa:sb,sl=lo===A?sa:sb;
      const T={uplift:['技術を授ける',`${sl}に技術と知識を授け、文明の成長を押し上げた`,`${sh}から授けられた知識で、文明を一気に伸ばした`],worship:['神として崇められる',`${sl}に見つかり、神として崇められるようになった`,`空から現れた${sh}を神として崇め、信仰を中心とした社会を作った`],gift:['言語の贈り物',`${sl}へ自分たちの言語と記録を贈った`,`${sh}から届いた言語と記録を解読し、世界の見方を変えた`]}[kind];
      evC(hi,lo,`${lo.name}へ${T[0]}`,`${sl}の文明と出会い、${T[1]}。`);
      evC(lo,hi,`${hi.name}からの${kind==='worship'?'来訪':'贈り物'}`,`${T[2]}。`);
      reviveCiv(lo);reviveCiv(hi);
      lo.outcome={kind:'allied',title:kind==='worship'?'来訪者を神と崇める':kind==='gift'?'異星の言語を受け取った':'異星の導きで成長した',text:`${sl}は${hi.name}の${sh}と出会い、${T[2]}。`};
      hi.outcome={kind:'allied',title:'異星の文明を導いた',text:`${sh}は${lo.name}の${sl}と出会い、${T[1]}。`};
    }else if(kind==='infect'){
      const hi=A.civ.stage>=B.civ.stage?A:B,lo=hi===A?B:A,sh=hi===A?sa:sb,sl=lo===A?sa:sb;
      const tl=Math.min(lo.civ.end,t+rg(R,50,400)),surv=R()<.45,tx=`${sh}との接触で持ち込まれた未知の病原体に免疫がなく、${sl}の文明は崩壊した。`;
      evC(hi,lo,`${lo.name}との接触`,`${sl}の文明と出会ったが、知らずに病原体を運んでしまった。`);
      evC(lo,hi,`${hi.name}との接触`,`${sh}の文明と出会ったが、その来訪者が持ち込んだ病原体が広がり始めた。`);
      endCiv(lo,tl,'接触による疫病',tx,surv?{kind:'ruins',title:'接触の疫病で崩壊、種は残る',text:tx+`生き延びた${sl}はいまも細々と続いている。`}:{kind:'extinct',title:`${sl}は滅んだ`,text:tx+`${sl}は絶えた。`},surv?null:'絶滅');
    }else if(kind==='zoo'){
      const hi=A.civ.stage>=B.civ.stage?A:B,lo=hi===A?B:A,sh=hi===A?sa:sb,sl=lo===A?sa:sb;
      evC(hi,lo,`${lo.name}を観察`,`${sl}の文明を発見したが、干渉せず遠くから見守ることに決めた(動物園仮説)。`);
      evC(lo,hi,`${hi.name}の視線`,`${sh}の文明に気づかれないまま、ずっと観察され続けている。`);
    }else{
      evC(A,B,`${B.name}との接触`,`${sb}の文明の存在を確認したが、互いに不干渉を選んだ。`);
      evC(B,A,`${A.name}との接触`,`${sa}の文明の存在を確認したが、互いに不干渉を選んだ。`);
    }
  });
}
function lastName(p){const l=p.lineage[p.lineage.length-1];return l?l.name:'(不明)'}

function finalize(p){
  p.events.sort((a,b)=>a.t-b.t);
  p.events.forEach(e=>{e.when=(p.civStart&&e.t>p.civStart)?`知性誕生から${fmt(e.t-p.civStart)}`:`惑星誕生から${fmt(e.t-p.tForm)}`});
  p.lineage.forEach(l=>{l.age=fmt(l.t-p.tForm)});
  const last=p.lineage[p.lineage.length-1];
  if(last){
    p.finalG=last.g;p.species=last.name;
    if(!last.fate)last.fate=(p.outcome&&p.outcome.kind==='extinct')?'絶滅':'現在も生存';
  }
}

/* 観測時点 tObs での姿。未来(tObs より後)は見えない */
function observe(p,tObs){
  const evs=p.events.filter(e=>e.t<=tObs);
  const lin=p.lineage.filter(l=>l.t<=tObs).map(l=>Object.assign({},l));
  const endEv=p.events.find(e=>e.kind==='end');
  const ongoing=!!p.civ&&(!endEv||endEv.t>tObs);
  const lifeOngoing=!p.civ&&p.tLife&&(!endEv||endEv.t>tObs);
  const hasLife=p.tLife&&p.tLife<=tObs;
  const lastL=lin[lin.length-1];
  let outcome=p.outcome,complete=true;
  if(ongoing||lifeOngoing||(!hasLife&&p.tLife)){
    complete=false;
    if(ongoing&&p.civStart<=tObs){
      const st=Math.min(CIV.length-1,evs.filter(e=>e.kind==='civ').length);
      const sp=lastL?lastL.name:'';
      const contacts=evs.filter(e=>e.kind==='contact'||e.kind==='cosmic');
      if(p.outcome.kind==='allied'&&contacts.length)outcome=p.outcome;
      else outcome={kind:'thriving',title:`${CIV[st].name}の途上`,text:`観測が終わる時点でも${sp}の文明は続いている。現在は「${CIV[st].name}」(カルダシェフ尺度 ${CIV[st].k})にあたる。`+contacts.map(c=>c.text).join('')};
    }else if(hasLife&&lastL){
      outcome={kind:'evolving',title:'進化の途上',text:`観測が終わる時点で${lastL.name}が暮らしているが、知性を持つ種はまだ現れていない。続きは誰にも分からない。`};
    }else{
      outcome={kind:'barren',title:'まだ生命はいない',text:'観測が終わる時点では、まだ生命が現れていない。'};
    }
    if(lastL&&(!p.outcome||p.outcome.kind!=='extinct'))lastL.fate='現在も生存';
  }
  return {events:evs,lineage:lin,outcome,complete,finalG:lastL?lastL.g:null,species:lastL?lastL.name:null};
}

/* 銀河規模の出来事(三体・Mass Effect・幼年期の終わり・プロジェクト・ヘイル・メアリー等から着想) */
const COSMICS=[
 {id:'nukewar',w:3,min:1,title:'銀河大戦',t:'宇宙に進出した文明どうしの報復が連鎖し、核と恒星破壊兵器が銀河じゅうで使われた。',doom:1,surv:.18,all:1},
 {id:'coreflare',w:2,min:1,title:'銀河中心の閃光',t:'銀河の中心核が活動期に入り、放射線の波が腕に沿って届いた。',doom:1,surv:.4,all:1},
 {id:'harvest',w:2,min:1,title:'収穫',t:'数万年に一度、高度な文明だけを刈り取る機構が目覚め、宇宙に進出した文明を片端から無力化した。',doom:1,surv:.1,space:1},
 {id:'machine',w:2,min:1,title:'殺戮機械の波',t:'銀河を巡回する自己複製機械が、知的生命の痕跡を探して解体し始めた。',doom:1,surv:.15,space:1},
 {id:'blight',w:1.5,min:1,title:'ブライトの拡散',t:'銀河の一角から、知性を飲み込む暴走した超知性が光速に近い速さで広がり始めた。',doom:1,surv:.1,all:1,half:1},
 {id:'vacuum',w:.7,min:1,title:'真空の崩壊',t:'どこかで始まった真空の相転移が光速で広がり、触れたものすべてを消していった。',doom:1,surv:0,all:1},
 {id:'simstop',w:.6,min:1,title:'シミュレーションの停止',t:'この宇宙を走らせていた計算が、何の前触れもなく停止した。',doom:1,surv:0,all:1},
 {id:'astro',w:2.5,min:1,title:'恒星が暗くなる',t:'星々の光を食べる微生物が現れ、恒星が次々と暗くなり始めた。',coop:1},
 {id:'federation',w:2.5,min:2,title:'銀河連邦の成立',t:'宇宙に進出した文明が条約で結ばれ、交易と防衛の連邦が生まれた。',ally:1},
 {id:'gate',w:1.5,min:2,title:'ゲート網の開通',t:'誰かが残した恒星間の門が開き、離れた星々が一瞬でつながった。',ally:1},
 {id:'transcend',w:1.5,min:1,title:'幼年期の終わり',t:'銀河を見守っていた上位の存在が、若い文明の子供たちを次の段階へ招いた。',asc:1},
 {id:'ac',w:1,min:1,title:'宇宙計算機の誕生',t:'あらゆる文明の計算機がつながって一つになり、宇宙の終わりに備える存在が生まれた。',asc:1}
];
function cosmicEvent(R,gal){
  const civs=gal.planets.filter(p=>p.civ);
  if(!civs.length||R()>.15)return;
  const maxS=Math.max.apply(null,civs.map(p=>p.civStart)),t=maxS+rg(R,1e3,2.5e4);
  const alive=civs.filter(p=>p.civ.start<t&&p.civ.end>t&&!(p.outcome.kind==='ascended'&&p.events.some(e=>e.kind==='end'&&e.t<=t)));
  if(!alive.length)return;
  const spaced=alive.filter(p=>p.civ.spaceStart!=null&&p.civ.spaceStart<t);
  const opts=COSMICS.filter(c=>(c.space||c.ally||c.id==='machine'?spaced.length:alive.length)>=c.min);
  if(!opts.length)return;
  const c=wpick(R,opts,x=>x.w);
  const hit=(c.space||c.ally||c.id==='machine')?spaced:alive;
  if(!hit.length)return;
  gal.cosmic={id:c.id,title:c.title,text:c.t,t,hit:hit.map(p=>p.id)};
  hit.forEach(p=>{
    const sp=lastName(p),tt=t+rg(R,20,3000);
    p.events.push({t,kind:'cosmic',title:c.title,text:c.t,major:true,g:null,planet:p.id});
    if(c.doom){
      if(c.half&&R()<.5)return;
      const surv=R()<c.surv,tx=`${c.title}が${sp}の星にも届き、文明は耐えられなかった。`;
      endCiv(p,tt,c.title+'で崩壊',tx,surv?{kind:'ruins',title:c.title+'で崩壊、種は残る',text:tx+`生き延びた${sp}はいまも細々と続いている。`}:{kind:'extinct',title:`${sp}は滅んだ`,text:tx+`${sp}は絶えた。`},surv?null:'絶滅');
    }else if(c.coop||c.ally){
      reviveCiv(p);
      const joined=c.coop&&hit.length<2?R()<.5:true;
      if(joined)p.outcome={kind:'allied',title:c.coop?'危機に文明が手を取り合った':c.title,text:c.coop?`${c.title}という共通の危機に、${sp}は他の文明と力を合わせ、いまも生き延びている。`:`${sp}は${c.title}に加わり、他の星々と結ばれて生きている。`};
      else{const tx=`${c.title}に単独で立ち向かったが、${sp}は耐えられなかった。`;endCiv(p,tt,c.title+'に敗れる',tx,{kind:'extinct',title:`${sp}は滅んだ`,text:tx+`${sp}は絶えた。`},'絶滅')}
    }else if(c.asc){
      trimTo(p,tt);p.events.push({t:tt,kind:'end',title:c.title,text:`${c.t}${sp}はその一部となって昇華した。`,major:true,g:null,planet:p.id});
      p.civ.ascended=c.title;p.civ.end=T_END;p.civ.alive=true;
      p.outcome={kind:'ascended',title:c.title,text:`${c.t}${sp}はその一部となって昇華した。`};
    }
  });
}

/* 神の一手: 現実にありえそうな、天体を使った介入だけを用意する */
const GOD_MAX=3;
const GODS=[
 {k:'seed',n:'生命の種を乗せた隕石',d:'別の星から飛んできた岩に微生物を乗せて落とす(パンスペルミア)。命のない星に生命が根づく確率が大きく上がる。',ok:p=>!p.tLife},
 {k:'water',n:'水を運ぶ彗星',d:'氷の多い彗星の軌道を変えて降らせる。乾いた星や凍った星が、生命を育てやすくなる。',ok:p=>!p.tLife},
 {k:'deflect',n:'小惑星の軌道をそらす',d:'その星に最初に起きるはずだった大災害を1つ避ける。進化が途切れにくくなる。',ok:p=>!!p.tLife},
 {k:'impact',n:'小惑星を落とす',d:'直径10キロ級の天体を落とす。大量絶滅が起き、生態系が作り直される。別の種が台頭することも、全滅することもある。',ok:p=>!!p.tLife},
 {k:'moon',n:'大きな衛星を捕まえさせる',d:'通りかかった小天体を衛星として捕まえさせる。月のように自転軸が安定し、気候の激変と大災害が減り、知性が育ちやすくなる。',ok:p=>!!p.tLife&&!p.civStart},
 {k:'res',n:'資源小惑星の捕獲',d:'金属の多い小惑星を軌道に引き込み、産業の時代の資源争いを和らげる。文明の崩壊リスクがおよそ35%下がる。',ok:p=>!!p.civ}
];

/* 運命の分類(珍しさの計算に使う) */
function fateKey(o){
  const k=o.outcome.kind;
  if(k==='extinct'||k==='ruins'){const e=o.events.slice().reverse().find(x=>x.kind==='end');return k+'|'+(e?e.title:'')}
  if(k==='evolving'){const l=o.lineage[o.lineage.length-1];return k+'|'+(l?l.stage:0)}
  return k+'|'+o.outcome.title;
}

/* 他の銀河から届く出来事(銀河衝突・信号・探査機・活動銀河核のジェット・移民船団) */
const EXTS=[
 {id:'collide',w:3,civ:0,title:'となりの銀河との衝突',t:'となりの銀河がゆっくりと重なり始めた。星どうしがぶつかることはほとんどないが、重力で軌道が乱れ、ガスが押し縮められて新しい星が次々に生まれた。夜空に二つ目の渦が広がっている。'},
 {id:'signal',w:2,civ:1,title:'別の銀河からの信号',t:'数百万光年先の銀河から、規則正しい電波が届いた。送り主はもう存在しないかもしれない。返事が向こうに届くのは数百万年後だ。'},
 {id:'probe',w:1.5,civ:1,title:'他の銀河の探査機',t:'銀河の外から、何百万年も旅してきた無人の探査機がたどり着いた。'},
 {id:'jet',w:1,civ:1,title:'隣の銀河核のジェット',t:'隣の銀河の中心にある超巨大ブラックホールが目覚め、噴き出したジェットの放射が銀河の一部をかすめた。'},
 {id:'refugee',w:1,civ:1,title:'他の銀河からの移民船団',t:'寿命を迎えた別の銀河から、移り住む先を探す船団がやってきた。'}
];
function externalEvent(R,gal){
  if(R()>.08)return;
  const t0=Math.min.apply(null,gal.planets.map(p=>p.tForm));
  const alive=t=>gal.planets.filter(p=>p.civ&&p.civ.start<t&&p.civ.end>t&&!(p.outcome.kind==='ascended'&&p.events.some(e=>e.kind==='end'&&e.t<=t)));
  const civs=gal.planets.filter(p=>p.civ&&p.civStart<gal.tObs);
  let x=wpick(R,EXTS,e=>e.w);
  if(x.civ&&!civs.length)x=EXTS[0];
  let t;
  if(!x.civ)t=rg(R,t0+3e8,gal.tObs-1e5);
  else{const c=pick(R,civs);t=Math.min(gal.tObs-10,c.civStart+rg(R,500,Math.max(800,Math.min(c.civ.end,gal.tObs)-c.civStart)))}
  const hitAll=x.civ?alive(t):gal.planets.filter(p=>p.tForm<t);
  if(!hitAll.length)return;
  gal.ext={id:x.id,title:x.title,text:x.t,t,hit:hitAll.map(p=>p.id),res:{}};
  hitAll.forEach(p=>{
    const sp=lastName(p),tt=t+rg(R,50,2000);
    let extra='';
    if(x.id==='signal'){extra=R()<.5?`${sp}は返事を送ることを決め、自分たちの歴史をまとめた信号を銀河の外へ放った。`:`${sp}は返事を送らなかった。見つかることの危険を恐れたからだ。`}
    else if(x.id==='probe'){
      if(R()<.6){extra=`探査機には、送り主の言語と科学が詰まっていた。${sp}はそれを読み解き、文明を大きく前に進めた。`;reviveCiv(p);p.outcome={kind:'allied',title:'他の銀河の知識を受け取った',text:`${sp}は、銀河の外から来た探査機の記録を読み解き、その知識とともに生きている。`};gal.ext.res[p.id]='good'}
      else{const surv=R()<.3,tx=`探査機は自己複製を始め、${sp}の星の資源を材料に増え続けた。`;extra=tx;endCiv(p,tt,'他の銀河の探査機による崩壊',tx,surv?{kind:'ruins',title:'探査機に星を食われ、種は残る',text:tx+`生き延びた${sp}はいまも細々と続いている。`}:{kind:'extinct',title:`${sp}は滅んだ`,text:tx+`${sp}は絶えた。`},surv?null:'絶滅');gal.ext.res[p.id]='bad'}
    }else if(x.id==='jet'){
      if(R()<.45){const surv=R()<.4,tx=`ジェットの放射が${sp}の星の大気を剥ぎ取り、文明は維持できなくなった。`;extra=tx;endCiv(p,tt,'銀河核のジェットで崩壊',tx,surv?{kind:'ruins',title:'ジェットに焼かれ、種は残る',text:tx+`生き延びた${sp}はいまも細々と続いている。`}:{kind:'extinct',title:`${sp}は滅んだ`,text:tx+`${sp}は絶えた。`},surv?null:'絶滅');gal.ext.res[p.id]='bad'}
      else extra=`${sp}の星はジェットの通り道から外れ、空が数年間明るく光っただけで済んだ。`;
    }else if(x.id==='refugee'){
      if(R()<.65){extra=`${sp}は船団を受け入れ、二つの種は同じ星で暮らし始めた。`;reviveCiv(p);p.outcome={kind:'allied',title:'他の銀河の移民と共に暮らす',text:`${sp}は、銀河の外から来た移民を受け入れ、共に生きている。`};gal.ext.res[p.id]='good'}
      else{const surv=R()<.4,tx=`船団との交渉は決裂し、住む場所をめぐる戦争になった。`;extra=tx;endCiv(p,tt,'移民船団との戦争',tx,surv?{kind:'ruins',title:'移民船団との戦争で崩壊、種は残る',text:tx+`生き延びた${sp}はいまも細々と続いている。`}:{kind:'extinct',title:`${sp}は滅んだ`,text:tx+`${sp}は絶えた。`},surv?null:'絶滅');gal.ext.res[p.id]='bad'}
    }
    p.events.push({t,kind:'cosmic',title:x.title,text:x.t+extra,major:x.id!=='collide'||p===hitAll[0],g:null,planet:p.id});
  });
}

/* 結末を変えない「名場面」。実際に起こりうる天体現象や発見だけを使う */
const WONDERS=[
 {need:'life',title:'大彗星の接近',t:'尾が空の半分を覆う大彗星が現れ、数か月のあいだ夜を照らした。'},
 {need:'life',title:'近くの超新星',t:'昼でも見える新しい星が空に現れ、数か月かけてゆっくり消えていった。距離が遠く、被害はなかった。'},
 {need:'life',title:'衛星が砕けて環になる',t:'近づきすぎた衛星が潮汐力で砕け、星のまわりに美しい環ができた。'},
 {need:'life',title:'もうひとつの生命',t:'地下深くで、今いる生き物とはまったく別の化学で動く微生物の群れが生まれていた(影の生物圏)。'},
 {need:'life',title:'海が光る',t:'光る微生物が大発生し、海全体が青く輝く夜が何年も続いた。'},
 {need:'mind',title:'正体不明の信号',t:'空の一点から、強く規則正しい電波が72秒間だけ届いた。その後、二度と聞こえることはなかった(ワオ!シグナル)。'},
 {need:'mind',title:'空に浮かぶ人工の影',t:'遠くの恒星の光が、自然ではありえない形で欠けて暗くなるのが観測された。誰かの巨大構造物かもしれない。'},
 {need:'mind',title:'星間天体の通過',t:'太陽系の外から来た細長い天体が、加速しながら通り過ぎていった。正体は最後まで分からなかった。'}
];
function wonders(R,gal){
  gal.planets.forEach(p=>{
    if(!p.tLife||p.tLife>gal.tObs)return;
    const civ=p.civStart!=null&&p.civStart<gal.tObs;
    if(R()>(civ?.55:.4))return;
    const pool=WONDERS.filter(w=>w.need==='life'||civ);
    const w=(civ&&R()<.6)?pick(R,pool.filter(x=>x.need==='mind')):pick(R,pool.filter(x=>x.need==='life'));
    const endE=p.events.find(e=>e.kind==='end'),lo=civ?p.civStart+300:p.tLife+1e7,hi=Math.min(gal.tObs-1,endE?endE.t-1:Infinity);
    if(!(hi>lo))return;
    const t=rg(R,lo,hi);
    p.events.push({t,kind:'wonder',title:w.title,text:w.t,major:true,g:null,planet:p.id});
    p.events.sort((a,b)=>a.t-b.t);
    p.events.forEach(e=>{if(!e.when)e.when=(p.civStart&&e.t>p.civStart)?`知性誕生から${fmt(e.t-p.civStart)}`:`惑星誕生から${fmt(e.t-p.tForm)}`});
  });
}
